  'patrol-fill': '/pages/inspection/index?kind=mid',
  'hazard-report': '/pages/project-check/records/index?checkType=1',
}

const openH5 = (route) => {
  const separator = route.includes('?') ? '&' : '?'
  const url = `${H5_BASE}${route}${separator}from=handheld`
  // #ifdef H5
  window.open(url, '_blank', 'noopener,noreferrer')
  // #endif
  // #ifndef H5
  uni.navigateTo({ url: `/pages/webview/index?url=${encodeURIComponent(url)}` })
  // #endif
}

const handleMenu = (item) => {
