    return
  }
  if (item.key === 'knowledge-base') {
    uni.navigateTo({ url: '/pages/knowledge/index' })
    return
  }
  if (item.key === 'facility') {
    uni.navigateTo({ url: '/pages_facility/facility/index' })
    return
  }
  if (item.key === 'repair-order-1') {
    uni.navigateTo({ url: '/pages_facility/issue/index?orderType=2' })
    return
  }
  if (item.key === 'report-order-2') {
    uni.navigateTo({ url: '/pages_facility/issue/index?orderType=1' })
    return
  }

  if (h5RouteMap[item.key]) {
    openH5(h5RouteMap[item.key])
    return
  }
  if (recordTypeRouteMap[item.key]) {
    uni.navigateTo({ url: `/pages_facility/record/index?type=${recordTypeRouteMap[item.key]}` })
    return
  }
  uni.showToast({ title: '功能建设中', icon: 'none' })
}

